const b = $input.first().json.body || {};
const GL = '46552447679363c70f7ef8.58193285';
const A = 'https://api.lokalise.com/api2/projects/';
const ps = (b.projects || []).filter(function(p){ return p.project_id !== GL; });
return ps.map(function(p){ return { json: { pid: p.project_id, name: p.name, url: A + p.project_id + '/keys?include_translations=1&disable_references=1&filter_archived=exclude&filter_translation_lang_ids=640&limit=500&pagination=cursor' } }; });

function norm(s) { return String(s || '').trim().replace(/[\s\u00a0]*[:.!]$/, '').trim().toLowerCase(); }
const EXACT = ['guaranteed satisfaction','256-bit ssl encryption','trusted by 7m+ users'];
const byP = {}; const errors = []; const near = []; let seen = 0; const pids = {};
for (const it of $input.all()) { const b = it.json.body || {};
  if (!Array.isArray(b.keys)) { errors.push({ s: it.json.statusCode, b: JSON.stringify(b).slice(0, 200) }); continue; }
  pids[b.project_id] = 1;
  for (const k of b.keys) { seen++; if (k.is_archived) continue;
    const en = (k.translations || []).find(function(t){ return t.language_iso === 'en'; }); if (!en || typeof en.translation !== 'string') continue;
    const n = norm(en.translation);
    if (EXACT.indexOf(n) >= 0) { (byP[b.project_id] = byP[b.project_id] || []).push(k.key_id); }
    else if (n.indexOf('guaranteed satisfaction') >= 0 || n.indexOf('satisfaction guaranteed') >= 0) near.push({ p: b.project_id, id: k.key_id, en: en.translation.slice(0, 150) });
  } }
const A = 'https://api.lokalise.com/api2/projects/';
const out = [];
for (const p in byP) { const ids = byP[p]; for (let i = 0; i < ids.length; i += 100) out.push({ json: { url: A + p + '/keys?include_translations=1&include_screenshots=1&disable_references=1&limit=500&filter_key_ids=' + ids.slice(i, i + 100).join(',') } }); }
const meta = { seen: seen, projectsRead: Object.keys(pids).length, errors: errors, near: near, matchProjects: Object.keys(byP).length };
if (!out.length) return [{ json: { url: '', meta: meta } }];
out[0].json.meta = meta; return out;

const meta = $('Match').first().json.meta;
const names = {}; for (const it of $('Config').all()) names[it.json.pid] = it.json.name;
const rows = []; const errors = [];
for (const it of $input.all()) { const b = it.json.body || {};
  if (!Array.isArray(b.keys)) { errors.push({ s: it.json.statusCode, b: JSON.stringify(b).slice(0, 200) }); continue; }
  for (const k of b.keys) { if (k.is_archived) continue;
    const kn = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || Object.values(k.key_name)[0]) : k.key_name;
    const t = {}; let en = '';
    for (const x of (k.translations || [])) { if (typeof x.translation !== 'string' || !x.translation) continue; if (x.language_iso === 'en') { en = x.translation; continue; } t[x.language_iso] = [x.translation, x.modified_at || '', x.modified_by_email || '', x.is_reviewed ? 1 : 0, x.is_unverified ? 1 : 0]; }
    rows.push({ p: b.project_id, pn: names[b.project_id], id: k.key_id, k: kn, en: en, file: k.filenames, tags: k.tags, shots: (k.screenshots || []).map(function(s){ return s.title || s.screenshot_id; }), t: t }); } }
return [{ json: { meta: meta, errors: errors, rows: rows } }];
